import pandas as pd
import pandera.pandas as pa

schema = pa.DataFrameSchema({
    "maquina": pa.Column(str, nullable=False),
    "temperatura": pa.Column(float, pa.Check.in_range(-20, 150)),
})
df = pd.DataFrame({"maquina": ["A", "B"], "temperatura": [25.0, 180.0]})
try:
    schema.validate(df, lazy=True)
except pa.errors.SchemaErrors as error:
    print(error.failure_cases)  # Detecta la temperatura de 180 grados.

