from fastapi import FastAPI
from pydantic import BaseModel, Field

app = FastAPI()
class Entrada(BaseModel):
    temperatura: float = Field(ge=-20, le=150)

@app.post("/predict")
def predict(entrada: Entrada):
    # Sustituye esta regla didáctica por la inferencia de tu modelo.
    return {"alarma": entrada.temperatura > 80}

# Ejemplo de body: {"temperatura": 90}
# Respuesta: {"alarma": true}
